CREATE TABLE IF NOT EXISTS users (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(300) NOT NULL, role VARCHAR(10) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS shipments (id BIGINT AUTO_INCREMENT PRIMARY KEY, tracking VARCHAR(40) NOT NULL UNIQUE, sender VARCHAR(100) NOT NULL, sender_contact VARCHAR(254) NOT NULL, sender_address VARCHAR(300) NOT NULL, recipient VARCHAR(100) NOT NULL, recipient_contact VARCHAR(254) NOT NULL, recipient_address VARCHAR(300) NOT NULL, weight DECIMAL(10,2) NOT NULL, service VARCHAR(20) NOT NULL, expected DATE NOT NULL, status VARCHAR(30) NOT NULL, agent_id BIGINT, version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(agent_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS events (id BIGINT AUTO_INCREMENT PRIMARY KEY, parcel_id BIGINT NOT NULL, status VARCHAR(30) NOT NULL, location VARCHAR(100) NOT NULL, note VARCHAR(500) NOT NULL, actor_id BIGINT NOT NULL, occurred_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(parcel_id) REFERENCES shipments(id), FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS alerts (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, parcel_id BIGINT NOT NULL, message VARCHAR(700) NOT NULL, is_read BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(parcel_id) REFERENCES shipments(id));
